/* struct _module_alias: the original module of a frozen module whose
   name differs from its source (orig NULL: not a stdlib module; a
   leading '<' marks the package itself) */
static const struct {
    const char *name;
    const char *orig;
} qp_frozen_aliases[] = {
    { "_frozen_importlib", "importlib._bootstrap" },
    { "_frozen_importlib_external", "importlib._bootstrap_external" },
    { "__hello_alias__", "__hello__" },
    { "__phello_alias__", "__hello__" },
    { "__phello_alias__.spam", "__hello__" },
    { "__phello__.__init__", "<__phello__" },
    { "__phello__.ham.__init__", "<__phello__.ham" },
    { "__hello_only__", NULL },
    { NULL },
};

/* The marshal data of each source (NULL: absent), set once by
   qp_set_frozen_modules() before any interpreter starts. */
static struct {
    const uint8_t *data;
    uint32_t size;
} qp_frozen_data[QP_FROZEN_NSOURCES];

static int qp_frozen_get_u32(const uint8_t **pp, const uint8_t *end, uint32_t *v)
{
    if ((size_t)(end - *pp) < 4)
        return -1;
    memcpy(v, *pp, 4);
    *pp += 4;
    return 0;
}

void qp_set_frozen_modules(const uint8_t *data, size_t size)
{
    const uint8_t *p = data, *end = data + size;
    const uint8_t *datas[QP_FROZEN_NSOURCES];
    uint32_t sizes[QP_FROZEN_NSOURCES];
    uint32_t n, len;
    int i;

    memset(qp_frozen_data, 0, sizeof(qp_frozen_data));
    if (!data || size < QP_FROZEN_MAGIC_LEN || memcmp(p, QP_FROZEN_MAGIC, QP_FROZEN_MAGIC_LEN))
        return;
    p += QP_FROZEN_MAGIC_LEN;
    if (qp_frozen_get_u32(&p, end, &n) < 0 || n != QP_FROZEN_NSOURCES)
        return;
    /* the blob of another table is ignored as a whole */
    for (i = 0; i < QP_FROZEN_NSOURCES; i++) {
        const char *id = qp_frozen_sources[i].id;
        if (qp_frozen_get_u32(&p, end, &len) < 0 || len != strlen(id) ||
            (size_t)(end - p) < len || memcmp(p, id, len))
            return;
        p += len;
        if (qp_frozen_get_u32(&p, end, &len) < 0 || (size_t)(end - p) < len)
            return;
        datas[i] = p;
        sizes[i] = len;
        p += len;
    }
    for (i = 0; i < QP_FROZEN_NSOURCES; i++) {
        qp_frozen_data[i].data = datas[i];
        qp_frozen_data[i].size = sizes[i];
    }
}

/* the module of `table` named `name` whose data is present */
static const QPFrozen *qp_frozen_search(const QPFrozen *table, const char *name)
{
    const QPFrozen *p;

    for (p = table; p->name; p++) {
        if (qp_frozen_data[p->source].data && !strcmp(name, p->name))
            return p;
    }
    return NULL;
}

/* use_frozen() */
static BOOL qp_frozen_enabled(JSContext *ctx)
{
    QPState *st = QP_STATE(ctx);

    if (st->override_frozen_modules > 0)
        return TRUE;
    if (st->override_frozen_modules < 0)
        return FALSE;
    return st->config.use_frozen_modules != 0;
}

/* look_up_frozen */
static const QPFrozen *qp_frozen_look_up(JSContext *ctx, const char *name)
{
    const QPFrozen *p;

    /* We always use the bootstrap modules. */
    if ((p = qp_frozen_search(qp_frozen_bootstrap, name)))
        return p;
    /* Frozen stdlib modules may be disabled. */
    if (qp_frozen_enabled(ctx)) {
        if ((p = qp_frozen_search(qp_frozen_stdlib, name)))
            return p;
        if ((p = qp_frozen_search(qp_frozen_test, name)))
            return p;
    }
    return NULL;
}

typedef enum {
    QP_FROZEN_OKAY,
    QP_FROZEN_BAD_NAME,     /* The given module name wasn't valid. */
    QP_FROZEN_NOT_FOUND,    /* It isn't a frozen module (or frozen modules are
                               disabled and it is not essential). */
    QP_FROZEN_INVALID,      /* The data does not contain executable code. */
} QPFrozenStatus;

typedef struct QPFrozenInfo {
    JSValueConst nameobj;   /* borrowed, QP_NULL if unset */
    const uint8_t *data;
    size_t size;
    BOOL is_package;
    BOOL has_origname;
    char origname[128];     /* the alias target, else the name */
} QPFrozenInfo;

/* set_frozen_error: ImportError(fmt % name, name=name) */
static JSValue qp_frozen_set_error(JSContext *ctx, QPFrozenStatus status, JSValueConst name)
{
    const char *fmt;
    JSValue msg, exc;

    switch (status) {
    case QP_FROZEN_INVALID:
        fmt = "Frozen object named %R is invalid";
        break;
    default:
        fmt = "No such frozen object named %R";
        break;
    }
    msg = qp_str_from_format(ctx, fmt, name);
    if (JS_IsException(msg))
        return msg;
    exc = qp_exc_new(ctx, QP_EXC(ctx, ImportError), 1, (JSValueConst *)&msg);
    JS_FreeValue(ctx, msg);
    if (JS_IsException(exc))
        return exc;
    if (qp_setattr(ctx, exc, QP_ATOM(ctx, name), name) < 0) {
        JS_FreeValue(ctx, exc);
        return JS_EXCEPTION;
    }
    return qp_raise_object(ctx, exc);
}

/* find_frozen(nameobj, info); never raises */
static QPFrozenStatus qp_frozen_find(JSContext *ctx, JSValueConst nameobj, QPFrozenInfo *info)
{
    const QPFrozen *p;
    const char *name, *orig;
    JSValue s;
    size_t len;
    int i;

    if (info) {
        memset(info, 0, sizeof(*info));
        info->nameobj = QP_NULL;
    }
    if (!qp_str_check(ctx, nameobj))
        return QP_FROZEN_BAD_NAME;
    /* _PyUnicode_AsUTF8NoNUL; errors are cleared */
    s = qp_str_value(ctx, nameobj);
    if (JS_IsException(s)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        return QP_FROZEN_BAD_NAME;
    }
    name = qp_str_utf8(ctx, s, &len);
    JS_FreeValue(ctx, s);
    if (!name) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        return QP_FROZEN_BAD_NAME;
    }
    if (strlen(name) != len) {
        JS_FreeCString(ctx, name);
        return QP_FROZEN_BAD_NAME;
    }
    p = qp_frozen_look_up(ctx, name);
    if (!p) {
        JS_FreeCString(ctx, name);
        return QP_FROZEN_NOT_FOUND;
    }
    if (info) {
        info->nameobj = nameobj;
        info->data = qp_frozen_data[p->source].data;
        info->size = qp_frozen_data[p->source].size;
        info->is_package = p->is_package;
        /* resolve_module_alias */
        orig = p->name;
        info->has_origname = TRUE;
        for (i = 0; qp_frozen_aliases[i].name; i++) {
            if (!strcmp(p->name, qp_frozen_aliases[i].name)) {
                orig = qp_frozen_aliases[i].orig;
                info->has_origname = orig != NULL;
                break;
            }
        }
        if (orig)
            snprintf(info->origname, sizeof(info->origname), "%s", orig);
    }
    JS_FreeCString(ctx, name);
    if (qp_frozen_data[p->source].size == 0)
        return QP_FROZEN_INVALID;
    return QP_FROZEN_OKAY;
}

/* unmarshal_frozen_code: PyMarshal_ReadObjectFromString(data) */
static JSValue qp_frozen_unmarshal(JSContext *ctx, const uint8_t *data, size_t size,
                                   JSValueConst nameobj)
{
    qp_marshal_RFILE rf;
    JSValue co;

    memset(&rf, 0, sizeof(rf));
    rf.ctx = ctx;
    rf.allow_code = 1;
    rf.readable = QP_NULL;
    rf.ptr = data ? data : (const uint8_t *)"";
    rf.end = rf.ptr + size;
    co = qp_marshal_read_object(&rf);
    qp_marshal_rfile_free(&rf);
    if (JS_IsException(co)) {
        /* Does not contain executable code. */
        JS_FreeValue(ctx, JS_GetException(ctx));
        return qp_frozen_set_error(ctx, QP_FROZEN_INVALID, nameobj);
    }
    if (!qp_typecheck(ctx, co, QP_TYPE(ctx, code))) {
        /* We stick with TypeError for backward compatibility. */
        JS_FreeValue(ctx, co);
        return qp_raise_type_error(ctx, "frozen object %R is not a code object", nameobj);
    }
    return co;
}

/* import_add_module(): sys.modules[name] if it is a module, else a new
   module stored there */
static JSValue qp_frozen_add_module(JSContext *ctx, JSValueConst name)
{
    JSValue mod;
    int r;

    r = qp_import_get_module(ctx, name, &mod);
    if (r < 0)
        return JS_EXCEPTION;
    if (r > 0) {
        if (qp_module_check(ctx, mod))
            return mod;
        JS_FreeValue(ctx, mod);
    }
    mod = qp_module_new(ctx, name);
    if (JS_IsException(mod))
        return mod;
    if (qp_setitem(ctx, QP_STATE(ctx)->modules, name, mod) < 0) {
        JS_FreeValue(ctx, mod);
        return JS_EXCEPTION;
    }
    return mod;
}

/* remove_module: del sys.modules[name], keeping the pending exception */
static void qp_frozen_remove_module(JSContext *ctx, JSValueConst name)
{
    JSValue modules = QP_STATE(ctx)->modules, exc = qp_exc_fetch(ctx), v;
    int r;

    if (qp_dict_check(ctx, modules)) {
        r = qp_dict_pop(ctx, modules, name, &v);
        if (r > 0)
            JS_FreeValue(ctx, v);
    } else {
        r = qp_delitem(ctx, modules, name);
    }
    if (r < 0)
        JS_FreeValue(ctx, qp_exc_fetch(ctx));
    JS_Throw(ctx, exc);
}

/* PyImport_ImportFrozenModuleObject: 1 for success, 0 if the module is
   not found, -1 with an exception set if the initialization failed. */
static int qp_import_frozen_module(JSContext *ctx, JSValueConst name)
{
    QPFrozenInfo info;
    QPFrozenStatus status;
    JSValue co, m, d = JS_UNDEFINED, l, origname, r;
    JSAtom atom;
    int err;

    status = qp_frozen_find(ctx, name, &info);
    if (status == QP_FROZEN_NOT_FOUND || status == QP_FROZEN_BAD_NAME)
        return 0;
    if (status != QP_FROZEN_OKAY) {
        qp_frozen_set_error(ctx, status, name);
        return -1;
    }
    co = qp_frozen_unmarshal(ctx, info.data, info.size, name);
    if (JS_IsException(co))
        return -1;
    if (info.is_package) {
        /* Set __path__ to the empty list */
        m = qp_frozen_add_module(ctx, name);
        if (JS_IsException(m))
            goto err_return;
        l = qp_list_new(ctx, 0);
        if (JS_IsException(l)) {
            JS_FreeValue(ctx, m);
            goto err_return;
        }
        err = qp_dict_set_item_atom(ctx, qp_module_get_dict(m), QP_ATOM(ctx, __path__), l);
        JS_FreeValue(ctx, l);
        JS_FreeValue(ctx, m);
        if (err < 0)
            goto err_return;
    }
    /* module_dict_for_exec */
    m = qp_frozen_add_module(ctx, name);
    if (JS_IsException(m))
        goto err_return;
    d = JS_DupValue(ctx, qp_module_get_dict(m));
    JS_FreeValue(ctx, m);
    if (qp_bi_ensure_builtins(ctx, d) < 0) {
        qp_frozen_remove_module(ctx, name);
        goto err_return;
    }
    /* exec_code_in_module */
    r = qp_eval_code(ctx, co, d, d);
    if (JS_IsException(r)) {
        qp_frozen_remove_module(ctx, name);
        goto err_return;
    }
    JS_FreeValue(ctx, r);
    err = qp_import_get_module(ctx, name, &m);
    if (err < 0)
        goto err_return;
    if (err == 0) {
        JSValue msg = qp_str_from_format(ctx, "Loaded module %R not found in sys.modules", name);
        if (!JS_IsException(msg)) {
            JSValue exc = qp_exc_new(ctx, QP_EXC(ctx, ImportError), 1, (JSValueConst *)&msg);
            JS_FreeValue(ctx, msg);
            if (!JS_IsException(exc))
                qp_raise_object(ctx, exc);
        }
        goto err_return;
    }
    JS_FreeValue(ctx, m);
    /* Set __origname__ (consumed in FrozenImporter._setup_module()). */
    origname = info.has_origname ? qp_str_from_cstr(ctx, info.origname) : qp_none();
    if (JS_IsException(origname))
        goto err_return;
    atom = JS_NewAtom(ctx, "__origname__");
    err = atom == JS_ATOM_NULL ? -1 : qp_dict_set_item_atom(ctx, d, atom, origname);
    JS_FreeAtom(ctx, atom);
    JS_FreeValue(ctx, origname);
    if (err < 0)
        goto err_return;
    JS_FreeValue(ctx, d);
    JS_FreeValue(ctx, co);
    return 1;

 err_return:
    JS_FreeValue(ctx, d);
    JS_FreeValue(ctx, co);
    return -1;
}

/* the bootstrap module `name` is frozen (data present) */
static BOOL qp_frozen_has_bootstrap(const char *name)
{
    return qp_frozen_search(qp_frozen_bootstrap, name) != NULL;
}

/* list_frozen_module_names */
static JSValue qp_frozen_module_names(JSContext *ctx)
{
    const QPFrozen *tables[3] = { qp_frozen_bootstrap, qp_frozen_stdlib, qp_frozen_test };
    BOOL enabled = qp_frozen_enabled(ctx);
    const QPFrozen *p;
    JSValue names, s;
    int i, r;

    names = qp_list_new(ctx, 0);
    if (JS_IsException(names))
        return names;
    /* We always use the bootstrap modules; frozen stdlib modules may be
       disabled. */
    for (i = 0; i < (enabled ? 3 : 1); i++) {
        for (p = tables[i]; p->name; p++) {
            if (!qp_frozen_data[p->source].data)
                continue;
            s = qp_str_from_cstr(ctx, p->name);
            if (JS_IsException(s)) {
                JS_FreeValue(ctx, names);
                return s;
            }
            r = qp_list_append(ctx, names, s);
            JS_FreeValue(ctx, s);
            if (r < 0) {
                JS_FreeValue(ctx, names);
                return JS_EXCEPTION;
            }
        }
    }
    return names;
}

/* ---- writing the frozen data at build time ----------------------------- */

/* `qpy --write-frozen-modules FILE DIR`: compile the frozen sources of the
   stdlib DIR/pylib into FILE and write the make dependencies of FILE on
   them (FILE.d).  Returns the exit status. */
int qp_write_frozen_modules(const char *path, const char *dir)
{
    static char *argv[] = { (char *)"", NULL };
    char home[PATH_MAX], fpath[PATH_MAX + 64];
    QPConfig cfg;
    JSRuntime *rt;
    JSContext *ctx;
    DynBuf d, deps;
    uint32_t u32;
    FILE *f;
    int i, ret = 1;

    if (!realpath(dir, home)) {
        perror(dir);
        return 1;
    }
    rt = JS_NewRuntime();
    if (!rt) {
        fprintf(stderr, "qpy: cannot allocate the runtime\n");
        return 1;
    }
    ctx = JS_NewContext(rt);
    if (!ctx) {
        fprintf(stderr, "qpy: cannot allocate the context\n");
        JS_FreeRuntime(rt);
        return 1;
    }
    memset(&cfg, 0, sizeof(cfg));
    cfg.hash_seed = "0";
    cfg.ignore_environment = 1;
    cfg.detached = 1;
    cfg.utf8_mode = 1;
    cfg.no_user_site = 1;
    cfg.no_site = 1;
    cfg.dont_write_bytecode = 1;
    cfg.int_max_str_digits = -1;
    cfg.lazy_imports = -1;
    cfg.argc = cfg.orig_argc = 1;
    cfg.argv = cfg.orig_argv = argv;
    cfg.home = home;
    dbuf_init(&d);
    dbuf_init(&deps);
    if (qp_state_init(ctx, &cfg) < 0)
        goto fail;
    dbuf_put(&d, (const uint8_t *)QP_FROZEN_MAGIC, QP_FROZEN_MAGIC_LEN);
    u32 = QP_FROZEN_NSOURCES;
    dbuf_put(&d, (const uint8_t *)&u32, 4);
    /* the dependency list of qp_base_write_deps: a first (skipped) entry,
       then the source files */
    dbuf_putc(&deps, '\0');
    for (i = 0; i < QP_FROZEN_NSOURCES; i++) {
        const QPFrozenSource *s = &qp_frozen_sources[i];
        char filename[160], *src = NULL;
        const char *text;
        size_t len;
        JSValue bc, code, data;
        const uint8_t *bytes;
        Py_ssize_t nbytes;

        if (s->path) {
            snprintf(fpath, sizeof(fpath), "%s/pylib/%s", home, s->path);
            src = qp_boot_read_file(ctx, fpath, &len);
            if (!src)
                goto fail;
            text = src;
            if (deps.size > 1)
                dbuf_putc(&deps, '\0');
            dbuf_putstr(&deps, fpath);
        } else {
            text = s->text;
            len = strlen(text);
        }
        /* Programs/_freeze_module: compile(text, "<frozen ID>", "exec",
           optimize=0, dont_inherit=True) */
        snprintf(filename, sizeof(filename), "<frozen %s>", s->id);
        bc = qp_compile_source(ctx, text, len, filename, JS_UNDEFINED, QP_INPUT_FILE, 0, 0, NULL);
        if (src)
            js_free(ctx, src);
        if (JS_IsException(bc))
            goto fail;
        code = qp_code_new(ctx, bc);
        JS_FreeValue(ctx, bc);
        if (JS_IsException(code))
            goto fail;
        data = qp_marshal_write_object(ctx, code, QP_MARSHAL_VERSION, 1);
        JS_FreeValue(ctx, code);
        if (JS_IsException(data))
            goto fail;
        bytes = qp_bytes_data(data, &nbytes);
        u32 = (uint32_t)strlen(s->id);
        dbuf_put(&d, (const uint8_t *)&u32, 4);
        dbuf_put(&d, (const uint8_t *)s->id, u32);
        u32 = (uint32_t)nbytes;
        dbuf_put(&d, (const uint8_t *)&u32, 4);
        dbuf_put(&d, bytes, nbytes);
        JS_FreeValue(ctx, data);
    }
    if (d.error || deps.error) {
        fprintf(stderr, "qpy: %s: out of memory\n", path);
        goto done;
    }
    f = fopen(path, "wb");
    if (!f || fwrite(d.buf, 1, d.size, f) != d.size || fclose(f) != 0) {
        perror(path);
        goto done;
    }
    if (qp_base_write_deps(path, (const char *)deps.buf, deps.size) < 0) {
        perror(path);
        goto done;
    }
    ret = 0;
    goto done;
 fail:
    qp_handle_uncaught(ctx);
 done:
    dbuf_free(&d);
    dbuf_free(&deps);
    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);
    return ret;
}
